-- ============================================================================
-- Inventario UTC - Esquema sql.docx + db/bd.sql + Clasificador Oficina (PDF)
-- Muebles de Oficina en General + Equipo de Oficina en General
-- Alineado con db/bd.sql: nfc, foto_url, foto_drive_id, codigo en aulas, triggers
-- ============================================================================

-- ================================================================
-- 1. LIMPIEZA TOTAL
-- ================================================================
DROP TABLE IF EXISTS bitacora_movimientos, prestamos, auditoria_detalle, auditorias,
                     bienes, adscripcion_persona, adscripcion, modelos, marcas,
                     articulos, familias_articulos, tipos_bien, aula, tipo_aula,
                     edificio, alumnos, profesor, persona, tipo_profesor,
                     motivo_de_movimiento, area, folio_siia, numero_resguardo, usuarios, roles CASCADE;
-- ==========================================
-- 2. CATÁLOGOS BASE (Nivel 0)
-- ==========================================
CREATE TABLE area (
    cve_area INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_area_padre INT NULL,
    abreviatura VARCHAR(5) NOT NULL,
    nombre VARCHAR(60) NOT NULL,
    activo BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE tipo_profesor (
    cve_tipo_profesor INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(30) NOT NULL,
    descripcion TEXT
);
CREATE TABLE roles (
    cve_rol INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE,
    descripcion TEXT,
    fecha_alta TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE persona (
    cve_persona INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL,
    apellido_paterno VARCHAR(35),
    apellido_materno VARCHAR(35),
    cve_carrera INT,
    cve_nivel_estudio INT,
    fecha_alta TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE usuarios (
    cve_usuario INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario VARCHAR(50) UNIQUE NOT NULL,
    contrasena_hash VARCHAR(255) NOT NULL,
    cve_rol INT REFERENCES roles(cve_rol),
    nombre VARCHAR(100),
    email VARCHAR(255),
    activo BOOLEAN DEFAULT TRUE,
    cve_persona INT REFERENCES persona(cve_persona),
    fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE edificio (
    cve_edificio INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(80),
    abreviatura VARCHAR(5),
    activo BOOLEAN DEFAULT TRUE
);
CREATE TABLE tipo_aula (
    cve_tipo_aula INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(45) NOT NULL
);
CREATE TABLE tipos_bien (
    cve_tipo INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clave VARCHAR(2) NOT NULL,
    nombre VARCHAR(100) NOT NULL
);
CREATE TABLE marcas (
    cve_marca INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_marca VARCHAR(50) NOT NULL UNIQUE
);
CREATE TABLE motivo_de_movimiento (
    cve_motivo INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_motivo VARCHAR(50) NOT NULL,
    requiere_aprobacion BOOLEAN DEFAULT FALSE
);
CREATE TABLE adscripcion (
    cve_adscripcion INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clave_adscripcion VARCHAR(20) NOT NULL UNIQUE,
    nombre_adscripcion VARCHAR(100) NOT NULL,
    estado BOOLEAN DEFAULT TRUE,
    fecha_registro DATE DEFAULT CURRENT_DATE
);
-- ==========================================
-- 3. TABLAS CON REFERENCIAS (Nivel 1)
-- ==========================================
CREATE TABLE profesor (
    cve_profesor INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_persona INT NOT NULL REFERENCES persona(cve_persona),
    cve_tipo_profesor INT NOT NULL REFERENCES tipo_profesor(cve_tipo_profesor),
    cve_area INT REFERENCES area(cve_area),
    activo BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE alumnos (
    cve_alumno INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_persona INT NOT NULL REFERENCES persona(cve_persona),
    matricula VARCHAR(15) NOT NULL,
    fecha_inscrito DATE NOT NULL,
    inscrito BOOLEAN NOT NULL,
    activo BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE aula (
    cve_aula INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_edificio INT NOT NULL REFERENCES edificio(cve_edificio),
    cve_tipo_aula INT NOT NULL REFERENCES tipo_aula(cve_tipo_aula),
    cve_profesor INT REFERENCES profesor(cve_profesor),
    cve_adscripcion INT REFERENCES adscripcion(cve_adscripcion),
    nombre VARCHAR(30) NOT NULL,
    codigo_barras VARCHAR(50) UNIQUE,
    codigo_qr VARCHAR(255) UNIQUE,
    capacidad SMALLINT
);
CREATE TABLE familias_articulos (
    cve_familia INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clave VARCHAR(2) NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    cve_tipo INT REFERENCES tipos_bien(cve_tipo)
);
CREATE TABLE modelos (
    cve_modelo INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_modelo VARCHAR(100) NOT NULL,
    cve_marca INT REFERENCES marcas(cve_marca),
    descripcion TEXT
);
-- ==========================================
-- 4. TABLAS CON REFERENCIAS (Nivel 2)
-- ==========================================
CREATE TABLE articulos (
    cve_articulo INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clave VARCHAR(4) NOT NULL UNIQUE,
    nombre VARCHAR(255) NOT NULL,
    cve_familia INT REFERENCES familias_articulos(cve_familia)
);
CREATE TABLE adscripcion_persona (
    cve_adscripcion_persona INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_adscripcion INT NOT NULL REFERENCES adscripcion(cve_adscripcion),
    cve_persona INT NOT NULL REFERENCES persona(cve_persona),
    activo BOOLEAN DEFAULT TRUE,
    fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
-- ==========================================
-- 5. TABLA DE BIENES (Inventario Central)
-- ==========================================
CREATE TABLE bienes (
    cve_bien INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    codigo_barras VARCHAR(50) UNIQUE,
    nfc VARCHAR(50) UNIQUE,
    codigo_qr VARCHAR(255) UNIQUE,
    no_serie VARCHAR(50) UNIQUE,
    no_factura VARCHAR(50) UNIQUE,
    descripcion TEXT,
    foto_url VARCHAR(500),
    foto_drive_id VARCHAR(255),
    cve_modelo INT REFERENCES modelos(cve_modelo),
    cve_articulo INT REFERENCES articulos(cve_articulo),
    costo_unitario DECIMAL(10, 2),
    cve_aula INT REFERENCES aula(cve_aula),
    cve_encargado INT REFERENCES persona(cve_persona),
    estado_fisico VARCHAR(20),
    estado_prestamo VARCHAR(20) DEFAULT 'disponible',
    activo BOOLEAN DEFAULT TRUE,
    fecha_registro DATE DEFAULT CURRENT_DATE
);
CREATE INDEX idx_bienes_qr ON bienes(codigo_qr);
-- ==========================================
-- 6. OPERACIONES Y DOCUMENTACIÓN
-- ==========================================
CREATE TABLE auditorias (
    cve_auditoria INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha_auditoria DATE DEFAULT CURRENT_DATE,
    cve_auditor INT REFERENCES persona(cve_persona),
    observaciones_generales TEXT
);
CREATE TABLE auditoria_detalle (
    cve_auditoria_det INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_auditoria INT REFERENCES auditorias(cve_auditoria),
    cve_bien INT REFERENCES bienes(cve_bien),
    encontrado BOOLEAN,
    estado_encontrado VARCHAR(50),
    observaciones_evidencia TEXT
);
CREATE TABLE prestamos (
    cve_prestamo INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_bien INT NOT NULL REFERENCES bienes(cve_bien),
    cve_persona_solicita INT NOT NULL REFERENCES persona(cve_persona),
    fecha_solicitud TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_devolucion_pactada TIMESTAMP,
    fecha_devolucion_real TIMESTAMP NULL,
    estado_prestamo VARCHAR(20) DEFAULT 'pendiente',
    observaciones TEXT
);
CREATE TABLE bitacora_movimientos (
    cve_movimiento INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cve_bien INT REFERENCES bienes(cve_bien),
    cve_motivo INT REFERENCES motivo_de_movimiento(cve_motivo),
    cve_persona_accion INT REFERENCES persona(cve_persona),
    fecha_movimiento TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    observaciones TEXT
);
CREATE TABLE folio_siia (
    cve_folio INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clave_siia VARCHAR(50) NOT NULL,
    cve_persona INT NOT NULL REFERENCES persona(cve_persona),
    fecha DATE DEFAULT CURRENT_DATE,
    hora TIME DEFAULT CURRENT_TIME,
    estado BOOLEAN DEFAULT TRUE
);
CREATE TABLE numero_resguardo (
    cve_resguardo_pk INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    no_resguardo VARCHAR(50) NOT NULL,
    cve_persona INT NOT NULL REFERENCES persona(cve_persona),
    fecha DATE DEFAULT CURRENT_DATE,
    hora TIME DEFAULT CURRENT_TIME,
    estado BOOLEAN DEFAULT TRUE,
    fecha_registro DATE DEFAULT CURRENT_DATE
);

-- ================================================================
-- 7. TRIGGERS
-- ================================================================
CREATE OR REPLACE FUNCTION fn_trg_actualizar_estado_prestamo()
RETURNS TRIGGER AS $$
BEGIN
    IF (NEW.estado_prestamo = 'aprobado') THEN
        UPDATE bienes SET estado_prestamo = 'prestado' WHERE cve_bien = NEW.cve_bien;
    ELSIF (NEW.estado_prestamo = 'devuelto') THEN
        UPDATE bienes SET estado_prestamo = 'disponible' WHERE cve_bien = NEW.cve_bien;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_actualizar_estado_prestamo
AFTER UPDATE ON prestamos FOR EACH ROW EXECUTE FUNCTION fn_trg_actualizar_estado_prestamo();

CREATE OR REPLACE FUNCTION fn_trg_log_estado_fisico()
RETURNS TRIGGER AS $$
BEGIN
    VALUES (NEW.cve_bien, 1, COALESCE(NEW.cve_encargado, 1), CURRENT_TIMESTAMP, 'El estado físico cambió a: ' || NEW.estado_fisico);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_log_estado_fisico
AFTER UPDATE ON bienes FOR EACH ROW
WHEN (OLD.estado_fisico IS DISTINCT FROM NEW.estado_fisico)
EXECUTE FUNCTION fn_trg_log_estado_fisico();

