-- 16. MOTIVOS DE MOVIMIENTO

-- Bienes distribuidos en DSM (100 registros, 6 aulas)
WITH catalogo AS (
    SELECT a.cve_articulo, a.nombre,
           row_number() OVER (ORDER BY random()) AS rn
    FROM articulos a
    LIMIT 100
)
    nombre, codigo_barras, nfc, codigo_qr, no_serie,
    costo_unitario, cve_modelo, cve_articulo,
    cve_aula, cve_encargado, estado_fisico, estado_prestamo, descripcion
)
SELECT
    LEFT(a.nombre, 100),
    'BAR-' || LPAD(a.rn::text, 3, '0'),
    'NFC-' || LPAD(a.rn::text, 3, '0'),
    'QR-' || LPAD(a.rn::text, 3, '0'),
    'SN-' || LPAD(a.rn::text, 3, '0') || '-' || floor(random() * 999)::int,
    (random() * 15000 + 500)::decimal(10, 2),
    (SELECT cve_modelo FROM modelos ORDER BY random() LIMIT 1),
    a.cve_articulo,
    CASE
        WHEN a.rn BETWEEN 1 AND 17  THEN (SELECT cve_aula FROM aula WHERE nombre = 'A-101')
        WHEN a.rn BETWEEN 18 AND 34 THEN (SELECT cve_aula FROM aula WHERE nombre = 'A-102')
        WHEN a.rn BETWEEN 35 AND 51 THEN (SELECT cve_aula FROM aula WHERE nombre = 'Lab-1')
        WHEN a.rn BETWEEN 52 AND 68 THEN (SELECT cve_aula FROM aula WHERE nombre = 'Lab-2')
        WHEN a.rn BETWEEN 69 AND 84 THEN (SELECT cve_aula FROM aula WHERE nombre = 'CC-1')
        ELSE (SELECT cve_aula FROM aula WHERE nombre = 'CC-2')
    END,
    CASE
        WHEN a.rn BETWEEN 1 AND 20  THEN 1   -- admin
        WHEN a.rn BETWEEN 21 AND 40 THEN 2   -- director
        WHEN a.rn BETWEEN 41 AND 60 THEN 3   -- profesor
        WHEN a.rn BETWEEN 61 AND 80 THEN 8   -- alumno
        ELSE 16                               -- Jorge (DSM)
    END,
    CASE
        WHEN a.rn % 5 = 0 THEN 'regular'
        ELSE 'bueno'
    END,
    CASE
        WHEN a.rn BETWEEN 1 AND 4 THEN 'prestado'
        WHEN a.rn BETWEEN 22 AND 25 THEN 'prestado'
        WHEN a.rn BETWEEN 41 AND 44 THEN 'prestado'
        WHEN a.rn BETWEEN 61 AND 62 THEN 'prestado'
        WHEN a.rn BETWEEN 85 AND 86 THEN 'prestado'
        ELSE 'disponible'
    END,
    'Equipo académico - Carrera DSM'
FROM catalogo a;

-- ========================================================================
-- POBLAMIENTO DE DATOS PARA PRESENTACIÓN
-- ========================================================================
DO $$
DECLARE
    id_persona_admin INT;
    id_persona_director INT;
    id_persona_profesor INT;
    id_persona_alumno INT;
    id_profesor_interno INT;
BEGIN
    -- Obtenemos los cve_persona DInÁMICAMENTE desde tu tabla usuarios
    SELECT cve_persona INTO id_persona_admin FROM usuarios WHERE usuario = 'admin' LIMIT 1;
    SELECT cve_persona INTO id_persona_director FROM usuarios WHERE usuario = 'director' LIMIT 1;
    SELECT cve_persona INTO id_persona_profesor FROM usuarios WHERE usuario = 'profesor' LIMIT 1;
    SELECT cve_persona INTO id_persona_alumno FROM usuarios WHERE usuario = 'alumno' LIMIT 1;
    -- 0. SALVAVIDAS: Asegurarnos de que las personas existan en la tabla 'persona'
    -- (Por si se corrió un script de limpieza que las borró pero quedaron vivas en 'usuarios')
    IF id_persona_admin IS NOT NULL AND NOT EXISTS (SELECT 1 FROM persona WHERE cve_persona = id_persona_admin) THEN
    END IF;
   
    IF id_persona_director IS NOT NULL AND NOT EXISTS (SELECT 1 FROM persona WHERE cve_persona = id_persona_director) THEN
    END IF;
    IF id_persona_profesor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM persona WHERE cve_persona = id_persona_profesor) THEN
    END IF;
    IF id_persona_alumno IS NOT NULL AND NOT EXISTS (SELECT 1 FROM persona WHERE cve_persona = id_persona_alumno) THEN
    END IF;
    -- 1. Insertamos en la tabla 'profesor' usando la id real de la persona
    IF id_persona_profesor IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM profesor WHERE cve_persona = id_persona_profesor) THEN
            VALUES (id_persona_profesor, 1, 1, true);
        END IF;
    END IF;
    -- 2. Insertamos en la tabla 'alumnos' usando la id real de la persona
    IF id_persona_alumno IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM alumnos WHERE cve_persona = id_persona_alumno) THEN
            VALUES (id_persona_alumno, 'MAT-2026-001', CURRENT_DATE, true, true);
        END IF;
    END IF;
    -- 3. Obtenemos el ID interno de profesor para asignarle aulas
    SELECT cve_profesor INTO id_profesor_interno FROM profesor WHERE cve_persona = id_persona_profesor LIMIT 1;
   
    IF id_profesor_interno IS NOT NULL THEN
        UPDATE aula SET cve_profesor = id_profesor_interno WHERE cve_aula IN (1, 2);
        UPDATE bienes SET cve_encargado = id_persona_profesor WHERE cve_aula IN (1, 2);
    END IF;
    -- 4. Generar Préstamos (Alumnos)
    IF id_persona_alumno IS NOT NULL THEN
        SELECT cve_bien, id_persona_alumno, CURRENT_TIMESTAMP - INTERVAL '1 day', CURRENT_TIMESTAMP + INTERVAL '3 days', 'pendiente'
        FROM bienes WHERE estado_prestamo = 'disponible' LIMIT 2;
        SELECT cve_bien, id_persona_alumno, CURRENT_TIMESTAMP - INTERVAL '5 days', CURRENT_TIMESTAMP + INTERVAL '2 days', 'aprobado'
        FROM bienes WHERE estado_prestamo = 'disponible' LIMIT 3 OFFSET 2;
    END IF;
    -- 5. Generar Préstamos (Profesor)
    IF id_persona_profesor IS NOT NULL THEN
        SELECT cve_bien, id_persona_profesor, CURRENT_TIMESTAMP - INTERVAL '10 days', CURRENT_TIMESTAMP - INTERVAL '1 day', 'por_devolver'
        FROM bienes WHERE estado_prestamo = 'disponible' LIMIT 2 OFFSET 5;
    END IF;
    -- 6. Actualizamos los bienes para reflejar los préstamos
    UPDATE bienes SET estado_prestamo = 'prestado'
    WHERE cve_bien IN (
        SELECT cve_bien FROM prestamos WHERE estado_prestamo IN ('aprobado', 'por_devolver')
    );
    -- 7. Asegurar que existan motivos de movimiento
    IF NOT EXISTS (SELECT 1 FROM motivo_de_movimiento WHERE cve_motivo = 1) THEN
    END IF;
    IF NOT EXISTS (SELECT 1 FROM motivo_de_movimiento WHERE cve_motivo = 2) THEN
    END IF;
    -- 8. Llenar la Bitácora de Movimientos
    IF id_persona_admin IS NOT NULL THEN
        SELECT cve_bien, 1, id_persona_admin, CURRENT_TIMESTAMP - INTERVAL '7 days', 'Revisión semestral aprobada'
        FROM bienes LIMIT 5;
    END IF;
    IF id_persona_profesor IS NOT NULL THEN
        SELECT cve_bien, 2, id_persona_profesor, CURRENT_TIMESTAMP - INTERVAL '2 days', 'Se mandó a mantenimiento de rutina'
        FROM bienes LIMIT 3 OFFSET 5;
    END IF;
    -- 9. Crear Auditorías
    IF id_persona_director IS NOT NULL THEN
        VALUES (CURRENT_TIMESTAMP - INTERVAL '30 days', 'Auditoría general por cierre de mes', id_persona_director);
    END IF;
    IF id_persona_admin IS NOT NULL THEN
        VALUES (CURRENT_TIMESTAMP - INTERVAL '2 days', 'Auditoría aleatoria en Edificio A', id_persona_admin);
    END IF;
END $$;

-- ========================================================================
-- DATOS ADICIONALES: préstamos, resguardos y folios SIIA (~25 c/u)
-- ========================================================================

-- Más préstamos para llegar a ~25 (ya hay ~7 del DO block)
SELECT
    b.cve_bien,
    (SELECT cve_persona FROM persona WHERE cve_persona BETWEEN 6 AND 15 ORDER BY random() LIMIT 1),
    CURRENT_TIMESTAMP - (random() * INTERVAL '60 days'),
    CURRENT_TIMESTAMP + (random() * INTERVAL '15 days'),
    (ARRAY['activo', 'activo', 'aprobado', 'por_devolver', 'devuelto', 'devuelto', 'devuelto', 'pendiente'])[floor(random() * 8 + 1)],
    'Préstamo de práctica'
FROM bienes b
WHERE b.cve_bien NOT IN (SELECT DISTINCT cve_bien FROM prestamos)
LIMIT 50;

-- Asegurar estado correcto en bienes para prestamos activos/aprobados
UPDATE bienes SET estado_prestamo = 'prestado'
WHERE cve_bien IN (SELECT cve_bien FROM prestamos WHERE estado_prestamo IN ('activo', 'aprobado', 'por_devolver'));

-- Número de resguardo (un resguardo por cada bien)
SELECT
    'RGTO-' || LPAD(b.cve_bien::text, 4, '0') || '-' || EXTRACT(YEAR FROM CURRENT_DATE)::text,
    COALESCE(b.cve_encargado, (SELECT cve_persona FROM persona ORDER BY random() LIMIT 1)),
    CURRENT_DATE - (floor(random() * 120)::int),
    TRUE
FROM bienes b
ORDER BY b.cve_bien
LIMIT 100;

-- Folios SIIA (un folio por cada bien)
SELECT
    'SIIA-' || LPAD(b.cve_bien::text, 4, '0'),
    COALESCE(b.cve_encargado, (SELECT cve_persona FROM persona ORDER BY random() LIMIT 1)),
    CURRENT_DATE - (floor(random() * 90)::int),
    TRUE
FROM bienes b
ORDER BY b.cve_bien
LIMIT 100;

